#include <bits/stdc++.h>
using namespace std;
typedef vector<uint16_t> U16;  // a JSON string as UTF-16 code units, like Python's json escapes

static int hexval(char c) { return isdigit((unsigned char)c) ? c - '0' : (tolower(c) - 'a' + 10); }

int main() {
    string in((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
    vector<U16> strs;
    for (size_t i = 0; i < in.size(); i++) {
        if (in[i] != '"') continue;
        U16 s;
        for (i++; in[i] != '"'; i++) {
            unsigned char c = in[i];
            if (c == '\\') {
                char e = in[++i];
                if (e == 'u') { s.push_back(hexval(in[i+1]) << 12 | hexval(in[i+2]) << 8 | hexval(in[i+3]) << 4 | hexval(in[i+4])); i += 4; }
                else if (e == 'n') s.push_back('\n');
                else if (e == 't') s.push_back('\t');
                else if (e == 'r') s.push_back('\r');
                else if (e == 'b') s.push_back('\b');
                else if (e == 'f') s.push_back('\f');
                else s.push_back(e);
            } else if (c < 0x80) {
                s.push_back(c);
            } else {  // raw UTF-8
                int len = c >= 0xF0 ? 4 : c >= 0xE0 ? 3 : 2;
                uint32_t cp = c & (0xFF >> (len + 1));
                for (int k = 1; k < len; k++) cp = cp << 6 | (in[i + k] & 0x3F);
                i += len - 1;
                if (cp >= 0x10000) { cp -= 0x10000; s.push_back(0xD800 | cp >> 10); s.push_back(0xDC00 | (cp & 0x3FF)); }
                else s.push_back(cp);
            }
        }
        strs.push_back(s);
    }
    const U16 SHIP_NA = {'N', '/', 'A'}, INSERT = {'I', 'N', 'S', 'E', 'R', 'T'};
    deque<U16> queue;
    vector<vector<U16>> out;
    for (size_t i = 0; i + 1 < strs.size(); i += 2) {
        if (strs[i] == INSERT) queue.push_back(strs[i + 1]);
        else if (queue.size() < 3) out.push_back({SHIP_NA});
        else {
            vector<U16> group(queue.begin(), queue.begin() + 3);
            queue.erase(queue.begin(), queue.begin() + 3);
            out.push_back(group);
        }
    }
    // Encode like json.dumps(ensure_ascii=True) with spaces written as  .
    string res = "[";
    char buf[8];
    for (size_t g = 0; g < out.size(); g++) {
        if (g) res += ',';
        res += '[';
        for (size_t k = 0; k < out[g].size(); k++) {
            if (k) res += ',';
            res += '"';
            for (uint16_t c : out[g][k]) {
                if (c == '"') res += "\\\"";
                else if (c == '\\') res += "\\\\";
                else if (c == '\n') res += "\\n";
                else if (c == '\r') res += "\\r";
                else if (c == '\t') res += "\\t";
                else if (c == '\b') res += "\\b";
                else if (c == '\f') res += "\\f";
                else if (c <= 0x20 || c >= 0x7F) { snprintf(buf, sizeof buf, "\\u%04x", c); res += buf; }
                else res += (char)c;
            }
            res += '"';
        }
        res += ']';
    }
    res += "]\n";
    fwrite(res.data(), 1, res.size(), stdout);
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static final String HEX = "0123456789abcdef";

    public static void main(String[] args) throws IOException {
        // Java strings are UTF-16, the same units Python's json escapes use.
        String in = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        List<String> strs = new ArrayList<>();
        for (int i = 0; i < in.length(); i++) {
            if (in.charAt(i) != '"') continue;
            StringBuilder sb = new StringBuilder();
            for (i++; in.charAt(i) != '"'; i++) {
                char c = in.charAt(i);
                if (c != '\\') { sb.append(c); continue; }
                char e = in.charAt(++i);
                switch (e) {
                    case 'u': sb.append((char) Integer.parseInt(in.substring(i + 1, i + 5), 16)); i += 4; break;
                    case 'n': sb.append('\n'); break;
                    case 't': sb.append('\t'); break;
                    case 'r': sb.append('\r'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    default: sb.append(e);
                }
            }
            strs.add(sb.toString());
        }
        ArrayDeque<String> queue = new ArrayDeque<>();
        List<String[]> out = new ArrayList<>();
        for (int i = 0; i + 1 < strs.size(); i += 2) {
            if (strs.get(i).equals("INSERT")) queue.add(strs.get(i + 1));
            else if (queue.size() < 3) out.add(new String[] {"N/A"});
            else out.add(new String[] {queue.poll(), queue.poll(), queue.poll()});
        }
        // Encode like json.dumps(ensure_ascii=True) with spaces written as  .
        StringBuilder sb = new StringBuilder("[");
        for (int g = 0; g < out.size(); g++) {
            if (g > 0) sb.append(',');
            sb.append('[');
            for (int k = 0; k < out.get(g).length; k++) {
                if (k > 0) sb.append(',');
                sb.append('"');
                for (char c : out.get(g)[k].toCharArray()) {
                    switch (c) {
                        case '"': sb.append("\\\""); break;
                        case '\\': sb.append("\\\\"); break;
                        case '\n': sb.append("\\n"); break;
                        case '\r': sb.append("\\r"); break;
                        case '\t': sb.append("\\t"); break;
                        case '\b': sb.append("\\b"); break;
                        case '\f': sb.append("\\f"); break;
                        default:
                            if (c <= 0x20 || c >= 0x7F) {
                                sb.append("\\u");
                                for (int shift = 12; shift >= 0; shift -= 4) sb.append(HEX.charAt((c >> shift) & 15));
                            } else sb.append(c);
                    }
                }
                sb.append('"');
            }
            sb.append(']');
        }
        sb.append("]\n");
        PrintStream ps = new PrintStream(new FileOutputStream(FileDescriptor.out), false, StandardCharsets.US_ASCII);
        ps.print(sb);
        ps.flush();
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
	"strconv"
	"unicode/utf16"
	"unicode/utf8"
)

// parseStrings returns every JSON string in data as UTF-16 code units,
// the same units Python's json escapes use (lone surrogates survive).
func parseStrings(data []byte) [][]uint16 {
	var strs [][]uint16
	for i := 0; i < len(data); i++ {
		if data[i] != '"' {
			continue
		}
		s := []uint16{}
		for i++; data[i] != '"'; {
			c := data[i]
			switch {
			case c == '\\':
				e := data[i+1]
				i += 2
				switch e {
				case 'u':
					v, _ := strconv.ParseUint(string(data[i:i+4]), 16, 16)
					s = append(s, uint16(v))
					i += 4
				case 'n':
					s = append(s, '\n')
				case 't':
					s = append(s, '\t')
				case 'r':
					s = append(s, '\r')
				case 'b':
					s = append(s, '\b')
				case 'f':
					s = append(s, '\f')
				default:
					s = append(s, uint16(e))
				}
			case c < utf8.RuneSelf:
				s = append(s, uint16(c))
				i++
			default: // raw UTF-8
				r, size := utf8.DecodeRune(data[i:])
				s = utf16.AppendRune(s, r)
				i += size
			}
		}
		strs = append(strs, s)
	}
	return strs
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	strs := parseStrings(data)
	insert := utf16.Encode([]rune("INSERT"))
	notAvailable := utf16.Encode([]rune("N/A"))
	var queue [][]uint16
	var out [][][]uint16
	for i := 0; i+1 < len(strs); i += 2 {
		if slices.Equal(strs[i], insert) {
			queue = append(queue, strs[i+1])
		} else if len(queue) < 3 {
			out = append(out, [][]uint16{notAvailable})
		} else {
			out = append(out, queue[:3:3])
			queue = queue[3:]
		}
	}
	// Encode like json.dumps(ensure_ascii=True) with spaces written as  .
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteByte('[')
	for g, group := range out {
		if g > 0 {
			w.WriteByte(',')
		}
		w.WriteByte('[')
		for k, s := range group {
			if k > 0 {
				w.WriteByte(',')
			}
			w.WriteByte('"')
			for _, c := range s {
				switch c {
				case '"':
					w.WriteString(`\"`)
				case '\\':
					w.WriteString(`\\`)
				case '\n':
					w.WriteString(`\n`)
				case '\r':
					w.WriteString(`\r`)
				case '\t':
					w.WriteString(`\t`)
				case '\b':
					w.WriteString(`\b`)
				case '\f':
					w.WriteString(`\f`)
				default:
					if c <= 0x20 || c >= 0x7F {
						fmt.Fprintf(w, `\u%04x`, c)
					} else {
						w.WriteByte(byte(c))
					}
				}
			}
			w.WriteByte('"')
		}
		w.WriteByte(']')
	}
	w.WriteString("]\n")
}
